32	// assertUnchanged 核对列表、详情与接口中的负责人、处理时间、分派记录均未被失败结果改写。
33	async function assertUnchanged(h, ticket, assignee, updatedAt, recordCount) {
34	  const s = await readState(h);
35	  assert.equal(s.fields["负责人"], assignee);
36	  assert.equal(s.fields["最近处理时间"], fmtMinute(updatedAt));
37	  assert.equal(s.history.length, recordCount);
38	  const row = rowOf(s, ticket.id);
39	  assert.equal(row.assignee, assignee);
40	  assert.equal(row.updated, fmtMinute(updatedAt));
41	  const persisted = await apiTicket(h, ticket.id);
42	  assert.equal(persisted.assignee, assignee);
43	  assert.equal(persisted.updatedAt, updatedAt);
44	  assert.equal((persisted.assignments || []).length, recordCount);
45	  return s;
46	}
