48	test("失败-1：保存失败响应（500），等待期间改过输入——不提示成功，记录不改写，草稿保留，重试须用户主动发起", async () => {
49	  const { h, ticket } = await setup();
50	  try {
51	    await setAssignee(h, "王芳");
52	    await submitAndWaitHeld(h);
53	    const opFirst = h.proxy.heldBody().operationId;
54	    await setAssignee(h, "李静"); // 等待期间改填另一个名字
55	
56	    await h.proxy.releaseNext({ status: 500, error: "unable to save assignment" });
57	    const s = await waitSettled(h);
58	
59	    // 此前提交的分派不能被提示成成功；失败要明确指向此前提交的负责人。
60	    assert.equal(s.notice.kind, "err");
