function newerTicket(a, b){
  var ta = a.updatedAt || "", tb = b.updatedAt || "";
  if (ta !== tb) return ta > tb;
  var la = Array.isArray(a.assignments) ? a.assignments.length : 0;
  var lb = Array.isArray(b.assignments) ? b.assignments.length : 0;
  return la >= lb;
}

